  "privFooter": "Confidentialité et stockage",
  "privTitle": "Confidentialité et stockage du navigateur",
  "privClose": "Fermer l’avis de confidentialité",
  "privWho": "Qui est responsable ?",
  "privWhat": "Ce que nous utilisons et pourquoi",
  "privStorage": "Stockage du navigateur",
  "privOther": "Autres fonctionnalités existantes",
  "privProviders": "Prestataires et transferts internationaux",
  "privRetention": "Conservation et suppression",
  "privRights": "Vos droits",
  "noticeReopen": "Avis sur le stockage",
  "noticeLabel": "Avis sur le stockage du navigateur",
  "noticeText": "Cook utilise le stockage du navigateur pour les fonctions de cuisine et de connexion que vous utilisez. Aucun stockage publicitaire ou analytique n’est ajouté.",
  "noticeClose": "Fermer l’avis sur le stockage",
  "privDraftLabel": "Brouillon — mis à jour le 28 octobre 2026.",
  "privDraft": "Les fonctions de compte sont en cours de test. Les informations ci-dessous sur l’exploitant et les services doivent être complétées avant le lancement public.",
  "privWho1": "Cook est exploité par [nom légal et adresse postale de l’exploitant]. Contactez [adresse e-mail dédiée à la confidentialité] pour toute question ou demande relative à la vie privée. Ces informations doivent être complétées avant l’ouverture des inscriptions.",
  "privWhat1": "Lorsque vous créez un compte, nous utilisons votre e-mail, un identifiant de compte, les données d’authentification par mot de passe et le statut de vérification pour fournir et sécuriser votre compte. Les mots de passe sont traités par le fournisseur d’authentification sous forme d’empreintes sécurisées ; Cook ne stocke aucun mot de passe lisible. Nous enregistrons le plan de votre cuisine, la langue choisie, le thème et les unités de mesure pour restaurer vos réglages sur tous vos appareils. Un e-mail et un mot de passe sont nécessaires pour avoir un compte ; vous pouvez consulter les recettes sans compte.",
  "privWhat2": "Le traitement des données du compte et des réglages est nécessaire pour fournir le service de compte que vous demandez (article 6, paragraphe 1, point b) du RGPD). Des données limitées de sécurité et de prévention des abus peuvent être traitées sur la base de l’intérêt légitime (article 6, paragraphe 1, point f)), sous réserve de nécessité et de mise en balance. Les e-mails de vérification et de réinitialisation du mot de passe sont des messages de service, pas de la prospection. La fonction de compte n’ajoute ni publicité ni mesure d’audience.",
  "privStorage1": "Cook utilise sessionStorage pour conserver votre cuisine, votre progression et vos choix d’une page à l’autre dans le même onglet. Lorsque vous êtes connecté, il contient aussi votre session d’authentification. Le navigateur efface normalement ces données à la fin de la session de l’onglet, mais la restauration de session du navigateur peut les conserver. La déconnexion efface les données d’onglet de Cook. La fermeture de l’avis sur le stockage n’est conservée que dans cet onglet. Les scripts de Cook ne déposent pas de cookies. Vos hébergeurs ou prestataires peuvent effectuer leurs propres traitements de sécurité, qui doivent être documentés avant le lancement.",
  "privStorage2": "OK et le bouton de fermeture de l’avis sur le stockage ne font que masquer l’avis. Ils n’autorisent ni mesure d’audience, ni publicité, ni autre suivi facultatif. Tout futur stockage non essentiel nécessitera un choix distinct avant de commencer, avec un refus et un retrait tout aussi simples.",
  "privOther1": "La fonction vocale actuelle de la liste de recettes demande à country.is un pays approximatif à partir de votre adresse IP afin de choisir une langue de reconnaissance vocale. Si vous utilisez la reconnaissance par micro, votre navigateur peut envoyer l’audio à son fournisseur de reconnaissance vocale. Vous pouvez aussi saisir les ingrédients au clavier. Ces fournisseurs, leurs politiques et la base légale de ces fonctions doivent être examinés avant le lancement public.",
  "privProviders1": "Fournisseur de comptes prévu : Supabase (PostgreSQL et authentification gérés), avec une région de base de données choisie dans l’UE. Fournisseur d’e-mail : [fournisseur]. Hébergeur du site : [fournisseur]. L’exploitant doit confirmer les fournisseurs réels, les contrats de sous-traitance, les sous-traitants ultérieurs, l’emplacement des journaux et tout transfert hors de l’EEE. Une région de base de données dans l’UE n’exclut pas à elle seule les transferts internationaux. Le cas échéant, indiquez la décision d’adéquation ou les garanties contractuelles applicables et comment en obtenir une copie.",
  "privRetention1": "Les réglages du compte sont conservés tant que votre compte est actif. Vous pouvez demander la suppression via le contact indiqué ci-dessus. Avant le lancement, l’exploitant doit préciser la procédure de traitement des demandes de suppression, le délai d’expiration des comptes non vérifiés et les durées de conservation des journaux de sécurité et des sauvegardes. Les données supprimées peuvent subsister dans des sauvegardes à accès restreint jusqu’à la fin de la durée de conservation documentée.",
  "privRights1": "Selon les conditions applicables, vous pouvez demander l’accès, la rectification, l’effacement, la limitation ou la portabilité, ou vous opposer à un traitement fondé sur l’intérêt légitime. Contactez l’exploitant ci-dessus ; les demandes reçoivent normalement une réponse sous un mois, toute prolongation légale étant expliquée. Vous pouvez introduire une réclamation auprès de votre autorité de contrôle, notamment la NAIH hongroise sur naih.hu. Cook n’utilise pas les réglages du compte pour des décisions automatisées produisant des effets juridiques ou des effets similaires significatifs.",
  "favOnly": "Favoris uniquement",
  "favAdd": "Ajouter aux favoris",
